1	/**
2	 * Server-side run store. Owns the candidate list and the simulation queue so
3	 * state survives a page refresh, and so swapping the local heuristic solver for
4	 * openEMS / the Devin session is a change confined to this file.
5	 */
6	import { phoneV1 } from "./device";
7	import { generateCandidates, isolationDb, scorePoint, simulate } from "./rf";
8	import type {
9	  AgentMessage,
10	  BandRequirement,
11	  Candidate,
12	  DeviceSpec,
13	  Job,
14	  SimResult,
15	} from "./types";
16	
17	const PLANNING_MS = 1600;
18	const PER_JOB_MS = 1500;
19	const CONCURRENCY = 3;
20	
21	interface Run {
22	  id: string;
23	  prompt: string;
24	  bandIds: string[];
25	  createdAt: number;
26	  spec: DeviceSpec;
27	  candidates: Candidate[];
28	  queue: Candidate[];
29	}
30	
31	const runs = new Map<string, Run>();
32	const resultCache = new Map<string, SimResult>();
33	
34	function bandById(spec: DeviceSpec, id: string) {
35	  const b = spec.requirements.bands.find((x) => x.id === id);
36	  if (!b) throw new Error(`unknown band ${id}`);
37	  return b;
38	}
39	
40	function resultFor(run: Run, cand: Candidate): SimResult {
41	  const key = `${run.id}::${cand.candidate_id}`;
42	  const cached = resultCache.get(key);
43	  if (cached) return cached;
44	  const r = simulate(run.spec, bandById(run.spec, cand.band_id), cand);
45	  resultCache.set(key, r);
46	  return r;
47	}
48	
49	/** Client-side constraint edits are applied to a per-run copy of the spec. */
50	export function applyOverrides(
51	  overrides: RunOverrides | undefined,
52	): DeviceSpec {
53	  if (!overrides) return phoneV1;
54	  return {
55	    ...phoneV1,
56	    requirements: {
57	      ...phoneV1.requirements,
58	      sar_limit: overrides.sar_limit ?? phoneV1.requirements.sar_limit,
59	      bands: phoneV1.requirements.bands.map((b) => ({
60	        ...b,
61	        ...(overrides.bands?.[b.id] ?? {}),
62	      })),
63	    },
64	  };
65	}
66	
67	export interface RunOverrides {
68	  sar_limit?: DeviceSpec["requirements"]["sar_limit"];
69	  bands?: Record<string, Partial<BandRequirement>>;
70	}
71	
72	export function createRun(
73	  prompt: string,
74	  bandIds: string[],
75	  perBand = 6,
76	  overrides?: RunOverrides,
77	): { runId: string; candidates: Candidate[] } {
78	  const spec = applyOverrides(overrides);
79	  const all = generateCandidates(spec, bandIds);
80	  const perBandTop = bandIds.map((bandId) =>
81	    all
82	      .filter((c) => c.band_id === bandId)
83	      .sort((a, b) => b.prior - a.prior)
84	      .slice(0, perBand),
85	  );
86	  // Interleave bands so early results cover the whole system, not one band.
87	  const queue: Candidate[] = [];
88	  for (let i = 0; i < perBand; i++) {
89	    for (const list of perBandTop) if (list[i]) queue.push(list[i]);
90	  }
91	
92	  const id = `run_${Date.now().toString(36)}`;
93	  runs.set(id, {
94	    id,
95	    prompt,
96	    bandIds,
97	    createdAt: Date.now(),
98	    spec,
99	    candidates: all,
100	    queue,
101	  });
102	  return { runId: id, candidates: all };
103	}
104	
105	function jobStates(run: Run, now: number): Job[] {
106	  return run.queue.map((c, i) => {
107	    const start = run.createdAt + PLANNING_MS + Math.floor(i / CONCURRENCY) * PER_JOB_MS;
108	    const end = start + PER_JOB_MS;
109	    let status: Job["status"] = "queued";
110	    let progress = 0;
111	    if (now >= end) {
112	      status = "complete";
113	      progress = 1;
114	    } else if (now >= start) {
115	      status = "running";
116	      progress = (now - start) / PER_JOB_MS;
117	    }
118	    return {
119	      job_id: `${run.id}__${c.candidate_id}`,
120	      candidate_id: c.candidate_id,
121	      band_id: c.band_id,
122	      status,
123	      progress: +progress.toFixed(3),
124	      started_at: now >= start ? start : undefined,
125	      finished_at: now >= end ? end : undefined,
126	    };
127	  });
128	}
129	
130	export interface RunSnapshot {
131	  runId: string;
132	  done: boolean;
133	  planning: boolean;
134	  jobs: Job[];
135	  results: Record<string, SimResult>;
136	  candidates: Candidate[];
137	  messages: AgentMessage[];
138	  placements: Record<string, string>;
139	  isolation: { a: string; b: string; db: number }[];
140	}
141	
142	export function readRun(runId: string): RunSnapshot | null {
143	  const run = runs.get(runId);
144	  if (!run) return null;
145	  const now = Date.now();
146	  const jobs = jobStates(run, now);
147	  const planning = now < run.createdAt + PLANNING_MS;
148	  const done = jobs.every((j) => j.status === "complete");
149	
150	  const results: Record<string, SimResult> = {};
151	  for (const j of jobs) {
152	    const cand = run.queue.find((c) => c.candidate_id === j.candidate_id)!;
153	    if (j.status === "complete") results[j.candidate_id] = resultFor(run, cand);
154	    else
155	      results[j.candidate_id] = {
156	        ...emptyResult(j.candidate_id),
157	        status: j.status,
158	      };
159	  }
160	
161	  const { placements, relocations } = assign(run, jobs, results);
162	
163	  const isolation: { a: string; b: string; db: number }[] = [];
164	  const placed = Object.entries(placements);
165	  for (let i = 0; i < placed.length; i++) {
166	    for (let k = i + 1; k < placed.length; k++) {
167	      const ca = run.queue.find((c) => c.candidate_id === placed[i][1])!;
168	      const cb = run.queue.find((c) => c.candidate_id === placed[k][1])!;
169	      const ba = bandById(run.spec, ca.band_id);
170	      const bb = bandById(run.spec, cb.band_id);
171	      isolation.push({
172	        a: ca.candidate_id,
173	        b: cb.candidate_id,
174	        db: isolationDb(
175	          ca.position_mm,
176	          cb.position_mm,
177	          (ba.f_low_ghz + ba.f_high_ghz) / 2,
178	          (bb.f_low_ghz + bb.f_high_ghz) / 2,
179	        ),
180	      });
181	    }
182	  }
183	
184	  return {
185	    runId: run.id,
186	    done,
187	    planning,
188	    jobs,
189	    results,
190	    candidates: run.candidates,
191	    messages: buildMessages(
192	      run,
193	      jobs,
194	      results,
195	      placements,
196	      isolation,
197	      relocations,
198	      planning,
199	      done,
200	    ),
201	    placements,
202	    isolation,
203	  };
204	}
