206	/**
207	 * One antenna per band, each on its own anchor. Bands are assigned
208	 * lowest-frequency first because they are the most clearance-hungry, and a
209	 * candidate is skipped when it couples too strongly into an already-placed
210	 * antenna or reuses an occupied anchor.
211	 */
212	function assign(run: Run, jobs: Job[], results: Record<string, SimResult>) {
213	  const placements: Record<string, string> = {};
214	  const relocations: { band_id: string; from: string; to: string; why: string }[] =
215	    [];
216	  const taken: Candidate[] = [];
217	
218	  const order = run.bandIds
219	    .slice()
220	    .sort(
221	      (a, b) =>
222	        bandById(run.spec, a).f_low_ghz - bandById(run.spec, b).f_low_ghz,
223	    );
224	
225	  for (const bandId of order) {
226	    const band = bandById(run.spec, bandId);
227	    const fc = (band.f_low_ghz + band.f_high_ghz) / 2;
228	    const ranked = jobs
229	      .filter((j) => j.band_id === bandId && j.status === "complete")
230	      .map((j) => run.queue.find((c) => c.candidate_id === j.candidate_id)!)
231	      .filter(Boolean)
232	      .sort((a, b) => rank(results[b.candidate_id]) - rank(results[a.candidate_id]));
233	    if (!ranked.length) continue;
234	
235	    let chosen: Candidate | undefined;
236	    let reason = "";
237	    for (const cand of ranked) {
238	      if (taken.some((t) => t.anchor_id === cand.anchor_id)) {
239	        reason = reason || `${cand.anchor_id} already occupied`;
240	        continue;
241	      }
242	      const worst = taken.reduce((acc, t) => {
243	        const tb = bandById(run.spec, t.band_id);
244	        const db = isolationDb(
245	          cand.position_mm,
246	          t.position_mm,
247	          fc,
248	          (tb.f_low_ghz + tb.f_high_ghz) / 2,
249	        );
250	        return Math.max(acc, db);
251	      }, -99);
252	      if (worst > run.spec.requirements.isolation_db_max) {
253	        reason =
254	          reason ||
255	          `${cand.anchor_id} would only give ${worst.toFixed(1)} dB isolation`;
256	        continue;
257	      }
258	      chosen = cand;
259	      break;
260	    }
261	
262	    if (!chosen) chosen = ranked[0];
263	    if (chosen.candidate_id !== ranked[0].candidate_id) {
264	      relocations.push({
265	        band_id: bandId,
266	        from: ranked[0].anchor_id,
267	        to: chosen.anchor_id,
268	        why: reason,
269	      });
270	    }
271	    placements[bandId] = chosen.candidate_id;
272	    taken.push(chosen);
273	  }
274	
275	  return { placements, relocations };
276	}
277	
278	/** Composite ranking used to pick the winner per band. */
279	export function rank(r: SimResult) {
280	  return (
281	    (r.meets_requirements ? 1 : 0) * 2 +
282	    Math.min(-r.s11_min_db / 20, 1) +
283	    r.efficiency +
284	    Math.min(r.bandwidth_mhz / 600, 1) * 0.5
285	  );
286	}
287	
288	function emptyResult(id: string): SimResult {
289	  return {
290	    candidate_id: id,
291	    status: "queued",
292	    runtime_s: 0,
293	    s11_curve: [],
294	    s11_min_db: 0,
295	    resonant_ghz: 0,
296	    bandwidth_mhz: 0,
297	    efficiency: 0,
298	    peak_gain_dbi: 0,
299	    vswr: 0,
300	    sar_w_per_kg: 0,
301	    meets_requirements: false,
302	    notes: "",
303	  };
304	}
305	
306	function buildMessages(
307	  run: Run,
308	  jobs: Job[],
309	  results: Record<string, SimResult>,
310	  placements: Record<string, string>,
311	  isolation: { a: string; b: string; db: number }[],
312	  relocations: { band_id: string; from: string; to: string; why: string }[],
313	  planning: boolean,
314	  done: boolean,
315	): AgentMessage[] {
316	  const m: AgentMessage[] = [];
317	  const spec = run.spec;
318	  let t = run.createdAt;
319	  const push = (kind: AgentMessage["kind"], text: string) =>
320	    m.push({ id: `m${m.length}`, role: "agent", kind, text, ts: (t += 1) });
321	
322	  push(
323	    "text",
324	    `Reading ${spec.name}. ${spec.components.length} named components, ` +
325	      `board ${spec.board.size_mm.join(" x ")} mm on ${spec.board.stackup} ` +
326	      `(er ${spec.board.epsilon_r}, tan-d ${spec.board.loss_tangent}).`,
327	  );
328	  push(
329	    "step",
330	    `Metal and lossy blocks that constrain placement: ` +
331	      `battery, camera module, PCB ground plane, taptic engine, loudspeaker. ` +
332	      `Enclosure back is glass (er 5.5), frame is aluminium and is treated as a radiator, not a blocker.`,
333	  );
334	
335	  for (const bandId of run.bandIds) {
336	    const band = bandById(spec, bandId);
337	    const top = run.queue.filter((c) => c.band_id === bandId);
338	    push(
339	      "step",
340	      `${band.name} (${band.f_low_ghz}-${band.f_high_ghz} GHz) needs >= ${band.clearance_mm} mm clearance. ` +
341	        `Shortlisted ${top.length} anchors, best prior at ${top[0]?.rationale ?? "n/a"}.`,
342	    );
343	  }
344	
345	  if (planning) return m;
346	
347	  for (const j of jobs) {
348	    const cand = run.queue.find((c) => c.candidate_id === j.candidate_id)!;
349	    const band = bandById(spec, j.band_id);
350	    if (j.status === "running") {
351	      push(
352	        "step",
353	        `Running FDTD sweep for ${cand.candidate_id} (${cand.antenna_type}, ${band.name}) at ${cand.position_mm.map((v) => v.toFixed(0)).join(", ")} mm.`,
354	      );
355	    } else if (j.status === "complete") {
356	      const r = results[j.candidate_id];
357	      push(
358	        "result",
359	        `${cand.candidate_id}: S11 ${r.s11_min_db.toFixed(1)} dB at ${r.resonant_ghz.toFixed(2)} GHz, ` +
360	          `BW ${r.bandwidth_mhz} MHz, eff ${(r.efficiency * 100).toFixed(0)}%, gain ${r.peak_gain_dbi} dBi, ` +
361	          `SAR ${r.sar_w_per_kg} W/kg -> ${r.meets_requirements ? "PASS" : "FAIL"}. ${r.notes}`,
362	      );
363	    }
364	  }
365	
366	  if (done) {
367	    for (const r of relocations) {
368	      const band = bandById(spec, r.band_id);
369	      push(
370	        "step",
371	        `${band.name}: best-scoring anchor was ${r.from}, but ${r.why}. Moved to ${r.to}.`,
372	      );
373	    }
374	    for (const [bandId, candId] of Object.entries(placements)) {
375	      const cand = run.queue.find((c) => c.candidate_id === candId)!;
376	      const band = bandById(spec, bandId);
377	      const s = scorePoint(spec, band, cand.position_mm);
378	      push(
379	        "text",
380	        `Recommendation for ${band.name}: ${cand.antenna_type} at ${cand.position_mm.map((v) => v.toFixed(1)).join(", ")} mm, ` +
381	          `radiator length ${cand.length_mm} mm, feed at ${cand.feed_point_mm.map((v) => v.toFixed(1)).join(", ")} mm. ` +
382	          `Keep-out ${band.clearance_mm} mm; nearest blocker is ${s.blocker} at ${s.clearance_mm.toFixed(1)} mm.`,
383	      );
384	    }
385	    const worst = isolation.slice().sort((a, b) => b.db - a.db)[0];
386	    if (worst) {
387	      push(
388	        "text",
389	        `Worst-case isolation between placed antennas is ${worst.db} dB (${worst.a} / ${worst.b}); ` +
390	          `target is <= ${spec.requirements.isolation_db_max} dB.`,
391	      );
392	    }
393	  }
394	  return m;
395	}
